T min_cost = std::numeric_limits<T>::max();
int best_axis = -1;

for (int axis = 0; axis < 3; ++axis) {
    T bin_width = (bmax[axis] - bmin[axis]) / static_cast<T>(BinBuffer<T>::NUM_BINS);
    T left_sa = 0, right_sa = 0;
    T left_count = 0, right_count = 0;

    for (int i = 0; i < BinBuffer<T>::NUM_BINS; ++i) {
        right_count += bins->counts[axis][i];
    }

    for (int i = 0; i < BinBuffer<T>::NUM_BINS - 1; ++i) {
        left_count += bins->counts[axis][i];
        right_count -= bins->counts[axis][i];

        if (left_count == 0 || right_count == 0) continue;

        T left_min = bmin[axis] + i * bin_width;
        T left_max = bmin[axis] + (i + 1) * bin_width;
        T right_min = left_max;
        T right_max = bmax[axis];

        std::array<T, 3> left_extents = {bmax.x - bmin.x, bmax.y - bmin.y, bmax.z - bmin.z};
        std::array<T, 3> right_extents = {bmax.x - bmin.x, bmax.y - bmin.y, bmax.z - bmin.z};
        left_extents[axis] = left_max - left_min;
        right_extents[axis] = right_max - right_min;

        left_sa = 2 * (left_extents[0] * left_extents[1] + left_extents[1] * left_extents[2] + left_extents[2] * left_extents[0]);
        right_sa = 2 * (right_extents[0] * right_extents[1] + right_extents[1] * right_extents[2] + right_extents[2] * right_extents[0]);

        T cost = left_count * left_sa + right_count * right_sa;
        if (cost < min_cost) {
            min_cost = cost;
            best_axis = axis;
            best_cut[axis] = left_max;
            best_bin[axis] = i + 1;
        }
    }
}

if (best_axis == -1) return false;

cut_pos[0] = best_cut[0];
cut_pos[1] = best_cut[1];
cut_pos[2] = best_cut[2];
*minCostAxis = best_axis;
return true;

